<?php
namespace App\Controllers;
use App\Models\Photo;use App\Core\Database;
final class StoreController{public function index():void{$photos=Photo::all(trim($_GET['q']??''));$events=Database::db()->query("SELECT e.*,COUNT(p.id) photos_count,COALESCE(MIN(p.preview_path),'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=1000&q=86') cover FROM events e LEFT JOIN photos p ON p.event_id=e.id GROUP BY e.id ORDER BY e.event_date DESC LIMIT 3")->fetchAll();view('store/index',['photos'=>$photos,'events'=>$events]);}public function photo():void{$photo=Photo::find((int)($_GET['id']??0));if(!$photo){http_response_code(404);exit('Foto no encontrada');}view('store/photo',['photo'=>$photo,'pageTitle'=>'Detalle de fotografía | Ultra','flowPage'=>true,'bodyClass'=>'inner','toplineRight'=>'DESCARGA INMEDIATA']);}}
